"""
Shared look for the cards generated by the Actions.

Mirrors the "grafite" theme of the hand-made cards in assets/ (same
palette, fonts, frame with the running border light and the "up" entrance),
so generated and hand-made cards read as one set.

Cards are always dark: they work on both GitHub themes, like those
cards. Desktop cards are 840 px wide and mobile cards 420 px, the same
widths those cards use, so text keeps the same scale across the README.
"""

from html import escape

DESKTOP_WIDTH = 840
MOBILE_WIDTH = 420

FUNDO = "#141414"
CAIXA = "#1C1C1C"
BORDA = "#2A2A2A"
BORDA2 = "#3A3A3A"
TINTA = "#F2F2F2"
CORPO = "#CFCFCF"
SUAVE = "#A0A0A0"
APAGADO = "#8A8A8A"
DESTAQUE = "#E6E6E6"
CLARO = "#FFFFFF"
ESCURO = "#8A8A8A"

SANS = "-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif"
SERIF = "Georgia,'Times New Roman',serif"

CSS = f"""
.up{{opacity:0;animation:up .9s cubic-bezier(.2,.7,.2,1) forwards}}
@keyframes up{{from{{opacity:0;transform:translateY(14px)}}to{{opacity:1;transform:none}}}}
.run{{stroke-dasharray:9 91;animation:run 7s linear infinite}}
@keyframes run{{to{{stroke-dashoffset:-100}}}}
.shine{{animation:shine 8s ease-in-out infinite}}
@keyframes shine{{0%,72%{{transform:translateX(-420px)}}100%{{transform:translateX(1300px)}}}}
.ln{{stroke-dasharray:100;stroke-dashoffset:100;animation:ln 1.4s ease forwards}}
@keyframes ln{{to{{stroke-dashoffset:0}}}}
.k{{font:700 10.5px {SANS};letter-spacing:1.6px;fill:{SUAVE}}}
.h{{font:700 17px {SANS};fill:{TINTA}}}
.n{{font:400 46px {SERIF};fill:url(#g)}}
.nm{{font:400 30px {SERIF};fill:url(#g)}}
.l{{font:500 13.5px {SANS};fill:{CORPO}}}
.s{{font:500 12px {SANS};fill:{SUAVE}}}
.f{{font:500 11px {SANS};fill:{APAGADO}}}
.ax{{font:500 11px {SANS};fill:{APAGADO}}}
.lg{{font:600 12.5px {SANS};fill:{CORPO}}}
.lp{{font:700 12.5px {SANS}}}
"""

DEFS = f"""<defs>
<linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="{CLARO}"/><stop offset="1" stop-color="{ESCURO}"/></linearGradient>
<linearGradient id="sh" x1="0" x2="1"><stop offset="0" stop-color="{CLARO}" stop-opacity="0"/><stop offset=".5" stop-color="{CLARO}" stop-opacity=".09"/><stop offset="1" stop-color="{CLARO}" stop-opacity="0"/></linearGradient>
<linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="{CLARO}" stop-opacity=".22"/><stop offset="1" stop-color="{CLARO}" stop-opacity="0"/></linearGradient>
</defs>"""


def delay(seconds):
    return f'style="animation-delay:{seconds:.2f}s"'


def text(value):
    return escape(str(value), quote=False)


def frame(width, height, rx=18):
    """Card background, the passing shine and the running border light."""
    return (
        f'<rect x="1" y="1" width="{width - 2}" height="{height - 2}" rx="{rx}" fill="{FUNDO}" stroke="{BORDA}"/>'
        f'<clipPath id="clip"><rect x="1" y="1" width="{width - 2}" height="{height - 2}" rx="{rx}"/></clipPath>'
        f'<g clip-path="url(#clip)"><g class="shine"><rect x="0" y="-20" width="150" height="{height + 40}" fill="url(#sh)" transform="skewX(-18)"/></g></g>'
        f'<rect class="run" x="1" y="1" width="{width - 2}" height="{height - 2}" rx="{rx}" fill="none" stroke="url(#g)" stroke-width="1.6" pathLength="100"/>'
    )


def svg(width, height, title, body):
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}" role="img" aria-label="{escape(title)}">\n'
        f"<title>{text(title)}</title>\n"
        f"<style>{CSS}</style>\n"
        f"{DEFS}\n"
        f"{frame(width, height)}\n"
        f"{body}\n"
        "</svg>\n"
    )
